    # pixels in the four cardinal directions (or by the grid edge).
    groups = defaultdict(list)
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or color == wall:
                continue

            top, bottom, left, right = 0, h - 1, 0, w - 1
            for rr in range(r - 1, -1, -1):
                if grid[rr][c] == wall:
                    top = rr + 1
                    break
            for rr in range(r + 1, h):
                if grid[rr][c] == wall:
                    bottom = rr - 1
                    break
            for cc in range(c - 1, -1, -1):
                if grid[r][cc] == wall:
                    left = cc + 1
                    break
            for cc in range(c + 1, w):
                if grid[r][cc] == wall:
                    right = cc - 1
                    break

            groups[(top, bottom, left, right)].append((r, c, color))

    out = [row[:] for row in grid]
    for (top, bottom, left, right), markers in groups.items():
        # The marker colors, ordered from the outer ring inward, form
        # the repeating palette for the nested rectangular rings.
        layers = defaultdict(Counter)
        for r, c, color in markers:
            depth = min(r - top, bottom - r, c - left, right - c)
            layers[depth][color] += 1

        palette = [
            layers[d].most_common(1)[0][0]
            for d in sorted(layers)
        ]
        if not palette:
            continue

        for r in range(top, bottom + 1):
            for c in range(left, right + 1):
                if grid[r][c] != wall:
                    depth = min(r - top, bottom - r, c - left, right - c)
                    out[r][c] = palette[depth % len(palette)]

    return out
